"""Synchronize supplier/RFQ projections atomically from authoritative records.

The application keeps writing records; trigger-managed tables stay read-only to runtime.
"""
from alembic import op

revision = '0004_proc_sync'
down_revision = '0003_proc_foundation'
branch_labels = None
depends_on = None

SQL = "-- Runtime writes only to records. This fixed trigger owns projection writes.\n-- Deferred supplier links allow an RFQ and its suppliers to be seeded in either order.\nALTER TABLE public.proc_rfq_invitations\n    ALTER CONSTRAINT proc_rfq_invitations_tenant_supplier_id_fkey\n    DEFERRABLE INITIALLY DEFERRED;\n\nCREATE FUNCTION public.sync_procurement_foundation()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path = pg_catalog, pg_temp\nAS $$\nDECLARE d jsonb;\nBEGIN\n    IF TG_OP = 'UPDATE' AND\n       (OLD.kind IN ('supplier','rfq') OR NEW.kind IN ('supplier','rfq')) AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Procurement record identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP = 'DELETE' THEN\n        IF OLD.kind = 'rfq' THEN\n            DELETE FROM public.proc_rfq_invitations WHERE tenant=OLD.tenant AND rfq_id=OLD.id;\n            DELETE FROM public.proc_rfq_lines WHERE tenant=OLD.tenant AND rfq_id=OLD.id;\n            DELETE FROM public.proc_rfqs WHERE tenant=OLD.tenant AND id=OLD.id;\n        ELSIF OLD.kind = 'supplier' THEN\n            -- A referenced supplier cannot be removed while an invitation depends on it.\n            DELETE FROM public.proc_suppliers WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    d := NEW.data::jsonb;\n    IF NEW.kind = 'supplier' THEN\n        INSERT INTO public.proc_suppliers(tenant,id,source_revision,name,category,approved,simulated)\n        VALUES (NEW.tenant,NEW.id,NEW.revision,d->>'name',d->>'category',\n                (d->>'approved')::boolean,(d->>'simulated')::boolean)\n        ON CONFLICT (tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n            name=EXCLUDED.name,category=EXCLUDED.category,approved=EXCLUDED.approved,simulated=EXCLUDED.simulated;\n    ELSIF NEW.kind = 'rfq' THEN\n        IF jsonb_typeof(d->'lines') IS DISTINCT FROM 'array' THEN\n            RAISE EXCEPTION 'RFQ lines must be an array' USING ERRCODE='23514';\n        END IF;\n        IF jsonb_array_length(d->'lines') < 1 THEN\n            RAISE EXCEPTION 'RFQ requires at least one line' USING ERRCODE='23514';\n        END IF;\n        INSERT INTO public.proc_rfqs(tenant,id,source_revision,title,due_date,status,owner_id,reviewer_id)\n        VALUES (NEW.tenant,NEW.id,NEW.revision,d->>'title',(d->>'due_date')::date,\n                d->>'status',d->>'owner',d->>'reviewer')\n        ON CONFLICT (tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n            title=EXCLUDED.title,due_date=EXCLUDED.due_date,status=EXCLUDED.status,\n            owner_id=EXCLUDED.owner_id,reviewer_id=EXCLUDED.reviewer_id;\n        DELETE FROM public.proc_rfq_lines WHERE tenant=NEW.tenant AND rfq_id=NEW.id;\n        INSERT INTO public.proc_rfq_lines\n        SELECT NEW.tenant,NEW.id,(l.n-1)::integer,l.v->>'sku',(l.v->>'quantity')::integer,\n               l.v->>'unit',l.v->'specs',l.v->>'evidence_id'\n        FROM jsonb_array_elements(d->'lines') WITH ORDINALITY l(v,n);\n        DELETE FROM public.proc_rfq_invitations WHERE tenant=NEW.tenant AND rfq_id=NEW.id;\n        INSERT INTO public.proc_rfq_invitations\n        SELECT NEW.tenant,NEW.id,i.v\n        FROM jsonb_array_elements_text(COALESCE(d->'invited','[]'::jsonb)) i(v);\n    END IF;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_foundation() FROM PUBLIC, supplypilot_app;\nCREATE TRIGGER records_procurement_sync\nAFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_foundation();\n\n-- Rebuild from authoritative records under the same migration transaction.\n-- This also removes projections whose source was deleted since migration 0003.\nDELETE FROM public.proc_rfq_invitations;\nDELETE FROM public.proc_rfq_lines;\nDELETE FROM public.proc_rfqs;\nDELETE FROM public.proc_suppliers;\nUPDATE public.records SET data=data WHERE kind IN ('supplier','rfq');\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Use the verified backup rollback procedure; disabling synchronization automatically is not supported.')
